 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 5 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            top = min(y for y, x in cells)
            bottom = max(y for y, x in cells)
            left = min(x for y, x in cells)
            right = max(x for y, x in cells)
            # Fill the zero-valued cavity within the outlined 5, leaving its 5 border intact.
            for y in range(top, bottom):
                for x in range(left, right + 1):
                    if grid[y][x] == 0 and any(grid[y][xx] == 5 for xx in range(x + 1, right + 1)):
                        out[y][x] = 2
            # Extend the top edge leftward across the row above the shape.
            if top > 0:
                for x in range(0, right):
                    if grid[top - 1][x] == 0:
                        out[top - 1][x] = 2
    return out
